import pkg from "../../package.json" with { type: "json" };

/** Product name used in output and generated files. */
export const TOOL_NAME = "policyguard";

/** Tool version, sourced from package.json so it cannot drift. */
export const TOOL_VERSION: string = pkg.version;

/** Directory (relative to the repository root) that holds PolicyGuard files. */
export const POLICYGUARD_DIR = ".policyguard";

/** Directory (relative to POLICYGUARD_DIR) that holds policy YAML files. */
export const POLICIES_SUBDIR = "policies";

/** Default configuration file name inside POLICYGUARD_DIR. */
export const CONFIG_FILE_NAME = "policyguard.config.json";

/** Directory (relative to POLICYGUARD_DIR) for caches and the last review result. */
export const CACHE_SUBDIR = "cache";

/** Supported policy file schema version. */
export const SUPPORTED_POLICY_VERSION = 1;

/** Supported configuration schema version. */
export const SUPPORTED_CONFIG_VERSION = 1;

/** Version of the JSON report schema emitted by `review --format json`. */
export const JSON_REPORT_SCHEMA_VERSION = "1.0";

/** Base refs tried in order when none is specified. */
export const FALLBACK_BASE_REFS: readonly string[] = ["origin/main", "main", "master"];

/** Default head ref. */
export const DEFAULT_HEAD_REF = "HEAD";

/** Process exit codes. */
export const EXIT_CODES = {
  ok: 0,
  blockingFindings: 1,
  failure: 2,
} as const;
