import { z } from "zod";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { CONFIG_FILE_NAME, POLICYGUARD_DIR, SUPPORTED_CONFIG_VERSION } from "./constants";
import { ConfigError } from "./errors";
import { err, ok, type Result } from "./result";

export const severitySchema = z.enum(["info", "warning", "error", "critical"]);

/** A path-scoped, auditable suppression. A written reason is mandatory. */
export const suppressionEntrySchema = z
  .object({
    ruleId: z.string().min(1).optional(),
    paths: z.array(z.string().min(1)).min(1).default(["**"]),
    reason: z.string().trim().min(1, "A suppression must state a reason"),
    author: z.string().min(1).optional(),
    expiresAt: z
      .string()
      .refine((value) => !Number.isNaN(Date.parse(value)), "expiresAt must be an ISO 8601 date")
      .optional(),
  })
  .strict();

export type SuppressionEntry = z.infer<typeof suppressionEntrySchema>;

const aiConfigSchema = z
  .object({
    enabled: z.boolean().default(false),
    provider: z.enum(["openai-compatible"]).default("openai-compatible"),
    model: z.string().min(1).default("gpt-4.1-mini"),
    baseUrl: z.url().optional(),
    apiKeyEnvVar: z
      .string()
      .regex(/^[A-Za-z_][A-Za-z0-9_]*$/, "apiKeyEnvVar must be an environment variable NAME")
      .default("POLICYGUARD_LLM_API_KEY"),
    maxFilesPerRequest: z.number().int().positive().max(100).default(10),
    maxContextChars: z.number().int().positive().default(24_000),
    redactSecrets: z.boolean().default(true),
  })
  .strict();

const configSchema = z
  .object({
    version: z.number().int(),
    project: z
      .object({
        languages: z.array(z.string().min(1)).default(["typescript"]),
        packageManager: z.enum(["pnpm", "npm", "yarn"]).optional(),
      })
      .strict()
      .prefault({}),
    review: z
      .object({
        defaultBase: z.string().min(1).optional(),
        ai: aiConfigSchema.prefault({}),
      })
      .strict()
      .prefault({}),
    paths: z
      .object({
        ui: z
          .array(z.string())
          .default(["src/app/**", "src/components/**", "src/pages/**", "src/ui/**"]),
        api: z.array(z.string()).default(["src/routes/**", "src/api/**"]),
        migrations: z
          .array(z.string())
          .default(["migrations/**", "database/migrations/**", "src/migrations/**"]),
        protected: z
          .array(z.string())
          .default([".github/workflows/**", "infra/**", "src/auth/**", "src/crypto/**"]),
        tests: z
          .array(z.string())
          .default(["**/*.test.*", "**/*.spec.*", "tests/**", "test/**", "**/__tests__/**"]),
      })
      .strict()
      .prefault({}),
    reporting: z
      .object({
        format: z.enum(["terminal", "json", "sarif"]).default("terminal"),
        failOn: severitySchema.default("error"),
      })
      .strict()
      .prefault({}),
    suppressions: z.array(suppressionEntrySchema).default([]),
  })
  .strict();

/** Validated PolicyGuard configuration with all defaults applied. */
export type PolicyGuardConfig = z.infer<typeof configSchema>;

/** Formats Zod issues as `path: message` lines. */
export function formatZodIssues(error: z.ZodError): string {
  return error.issues
    .map((issue) => {
      const location = issue.path.length > 0 ? issue.path.map(String).join(".") : "(root)";
      return `  - ${location}: ${issue.message}`;
    })
    .join("\n");
}

/** Parses an unknown value as configuration. */
export function parseConfig(input: unknown, file?: string): Result<PolicyGuardConfig, ConfigError> {
  const parsed = configSchema.safeParse(input);
  if (!parsed.success) {
    return err(
      new ConfigError(
        "config-invalid",
        `Invalid configuration:\n${formatZodIssues(parsed.error)}`,
        {
          ...(file === undefined ? {} : { file }),
          suggestion: "Fix the listed fields. See docs/configuration.md for every option.",
        },
      ),
    );
  }
  if (parsed.data.version !== SUPPORTED_CONFIG_VERSION) {
    return err(
      new ConfigError(
        "config-invalid",
        `Unsupported configuration version ${parsed.data.version}. Supported: ${SUPPORTED_CONFIG_VERSION}.`,
        { ...(file === undefined ? {} : { file }) },
      ),
    );
  }
  return ok(parsed.data);
}

/** Returns the configuration used when no config file exists. */
export function defaultConfig(): PolicyGuardConfig {
  const result = parseConfig({ version: SUPPORTED_CONFIG_VERSION });
  if (!result.ok) throw result.error;
  return result.value;
}

export interface LoadedConfig {
  readonly config: PolicyGuardConfig;
  /** Absolute path of the file the config came from, or undefined when defaults are used. */
  readonly sourcePath?: string;
}

/**
 * Loads configuration. An explicit path must exist; otherwise
 * `.policyguard/policyguard.config.json` is optional and defaults apply.
 */
export async function loadConfig(
  repositoryPath: string,
  explicitPath?: string,
): Promise<Result<LoadedConfig, ConfigError>> {
  const target = explicitPath
    ? path.resolve(repositoryPath, explicitPath)
    : path.join(repositoryPath, POLICYGUARD_DIR, CONFIG_FILE_NAME);

  let raw: string;
  try {
    raw = await readFile(target, "utf8");
  } catch (cause) {
    if (explicitPath === undefined && isNotFound(cause)) return ok({ config: defaultConfig() });
    return err(
      new ConfigError(
        isNotFound(cause) ? "config-not-found" : "config-invalid",
        `Cannot read configuration file: ${target}`,
        { file: target, cause, suggestion: "Check the path or run `policyguard init`." },
      ),
    );
  }

  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch (cause) {
    return err(
      new ConfigError("config-invalid", `Configuration is not valid JSON: ${target}`, {
        file: target,
        cause,
      }),
    );
  }

  const parsed = parseConfig(json, target);
  return parsed.ok ? ok({ config: parsed.value, sourcePath: target }) : parsed;
}

function isNotFound(cause: unknown): boolean {
  return (cause as NodeJS.ErrnoException | undefined)?.code === "ENOENT";
}
